import pickle
import base64
from datetime import datetime

with open('/app/report_data.pkl', 'rb') as f:
    data = pickle.load(f)

kpis = data['kpis']
cat_stats = data['cat_stats']
subcat_stats = data['subcat_stats']
price_seg_stats = data['price_seg_stats']
discount_seg_stats = data['discount_seg_stats']
top_engaged = data['top_engaged']
positive_words = data['positive_words']
negative_words = data['negative_words']
positive_titles = data['positive_titles']
negative_titles = data['negative_titles']
charts = data['charts']

# Helper for tables
def html_table(headers, rows, align=None):
    if align is None:
        align = ['left'] * len(headers)
    html = '<table><thead><tr>'
    for h, a in zip(headers, align):
        html += f'<th style="text-align:{a}">{h}</th>'
    html += '</tr></thead><tbody>'
    for row in rows:
        html += '<tr>'
        for cell, a in zip(row, align):
            html += f'<td style="text-align:{a}">{cell}</td>'
        html += '</tr>'
    html += '</tbody></table>'
    return html

# Prepare category table rows
cat_rows = []
for _, r in cat_stats.head(10).iterrows():
    cat_rows.append([
        r['top_category'],
        f"{r['product_count']:,}",
        f"{r['avg_rating']:.2f}",
        f"{r['avg_discount']:.1f}%",
        f"{r['median_rating_count']:,.0f}",
        f"{r['total_reviews']:,.0f}"
    ])

# Sub-category rows
subcat_rows = []
for _, r in subcat_stats.iterrows():
    subcat_rows.append([
        r['top_category'],
        r['sub_category'],
        f"{r['product_count']:,}",
        f"{r['avg_rating']:.2f}",
        f"{r['avg_discount']:.1f}%"
    ])

# Price segment rows
price_rows = []
for _, r in price_seg_stats.iterrows():
    price_rows.append([
        str(r['price_segment']),
        f"{r['product_count']:,}",
        f"{r['avg_rating']:.2f}",
        f"{r['avg_discount']:.1f}%",
        f"{r['median_rating_count']:,.0f}"
    ])

# Discount segment rows
discount_rows = []
for _, r in discount_seg_stats.iterrows():
    discount_rows.append([
        str(r['discount_segment']),
        f"{r['product_count']:,}",
        f"{r['avg_rating']:.2f}",
        f"{r['avg_discount']:.1f}%",
        f"{r['median_rating_count']:,.0f}"
    ])

# Top engaged rows
engaged_rows = []
for _, r in top_engaged.iterrows():
    name = r['product_name'][:60] + ('...' if len(r['product_name']) > 60 else '')
    engaged_rows.append([
        name,
        r['top_category'],
        f"₹{r['discounted_price_num']:,.0f}",
        f"{r['discount_percentage_num']:.0f}%",
        f"{r['rating_num']:.1f}",
        f"{r['rating_count_num']:,}"
    ])

# Sentiment samples
pos_sample = [t for t in positive_titles if len(t) < 100][:8]
neg_sample = [t for t in negative_titles if len(t) < 100][:8]

# Best/worst categories
best_cat = cat_stats.sort_values('avg_rating', ascending=False).iloc[0]
worst_cat = cat_stats.sort_values('avg_rating', ascending=True).iloc[0]
most_engaged_cat = cat_stats.sort_values('total_reviews', ascending=False).iloc[0]

# Build HTML
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Product Catalog Performance & Customer Sentiment Analysis</title>
<style>
:root {{
  --primary: #1a237e;
  --accent: #00acc1;
  --success: #2e7d32;
  --warning: #f57c00;
  --danger: #c62828;
  --bg: #f5f7fa;
  --card: #ffffff;
  --text: #263238;
  --muted: #607d8b;
  --border: #e0e6ed;
}}
* {{ box-sizing: border-box; }}
body {{
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  margin: 0;
  padding: 0;
}}
.container {{
  max-width: 1200px;
  margin: 0 auto;
  padding: 30px 20px;
}}
header {{
  background: linear-gradient(135deg, var(--primary) 0%, #283593 100%);
  color: white;
  padding: 40px 30px;
  border-radius: 12px;
  margin-bottom: 30px;
  box-shadow: 0 4px 20px rgba(26,35,126,0.2);
}}
header h1 {{
  margin: 0 0 10px 0;
  font-size: 1.9rem;
  font-weight: 700;
}}
header p {{
  margin: 0;
  opacity: 0.9;
  font-size: 1.05rem;
}}
.meta {{
  font-size: 0.85rem;
  opacity: 0.75;
  margin-top: 12px;
}}
.kpi-grid {{
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  margin-bottom: 30px;
}}
.kpi-card {{
  background: var(--card);
  border-radius: 10px;
  padding: 22px 18px;
  text-align: center;
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
  border-top: 4px solid var(--accent);
}}
.kpi-value {{
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 4px;
}}
.kpi-label {{
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}}
.section {{
  background: var(--card);
  border-radius: 10px;
  padding: 28px 30px;
  margin-bottom: 24px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}}
.section h2 {{
  margin: 0 0 18px 0;
  font-size: 1.35rem;
  color: var(--primary);
  border-left: 4px solid var(--accent);
  padding-left: 12px;
}}
.section h3 {{
  margin: 24px 0 12px 0;
  font-size: 1.1rem;
  color: #37474f;
}}
.chart {{
  margin: 18px 0;
  text-align: center;
}}
.chart img {{
  max-width: 100%;
  height: auto;
  border-radius: 8px;
  border: 1px solid var(--border);
}}
table {{
  width: 100%;
  border-collapse: collapse;
  margin: 14px 0 20px 0;
  font-size: 0.92rem;
}}
th, td {{
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}}
th {{
  background: #eceff1;
  color: var(--primary);
  font-weight: 600;
  text-align: left;
}}
tr:hover {{ background: #f8fafc; }}
.insight-box {{
  background: #e3f2fd;
  border-left: 4px solid var(--accent);
  padding: 14px 18px;
  border-radius: 6px;
  margin: 14px 0;
  font-size: 0.95rem;
}}
.insight-box strong {{
  color: var(--primary);
}}
.recommendation {{
  background: #e8f5e9;
  border-left: 4px solid var(--success);
  padding: 16px 18px;
  border-radius: 6px;
  margin: 14px 0;
}}
.recommendation h4 {{
  margin: 0 0 6px 0;
  color: var(--success);
  font-size: 1rem;
}}
.recommendation p {{
  margin: 0;
  font-size: 0.95rem;
}}
.tag {{
  display: inline-block;
  padding: 3px 10px;
  border-radius: 12px;
  font-size: 0.78rem;
  font-weight: 600;
  margin-right: 6px;
}}
.tag-good {{ background: #c8e6c9; color: var(--success); }}
.tag-warn {{ background: #ffe0b2; color: var(--warning); }}
.tag-bad {{ background: #ffcdd2; color: var(--danger); }}
.two-col {{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}}
@media (max-width: 800px) {{
  .two-col {{ grid-template-columns: 1fr; }}
}}
.sentiment-list {{
  columns: 2;
  column-gap: 20px;
  font-size: 0.9rem;
}}
.sentiment-list li {{
  break-inside: avoid;
  margin-bottom: 6px;
}}
footer {{
  text-align: center;
  color: var(--muted);
  font-size: 0.85rem;
  padding: 20px;
}}
</style>
</head>
<body>
<div class="container">

<header>
  <h1>Amazon Product Catalog Performance & Customer Sentiment Analysis</h1>
  <p>A comprehensive analysis of {kpis['total_products']:,} Amazon products examining pricing strategies, discount effectiveness, customer ratings, and category-level performance.</p>
  <div class="meta">Generated: {datetime.now().strftime('%B %d, %Y')} &nbsp;|&nbsp; Dataset: Amazon India (Kaggle) &nbsp;|&nbsp; Valid Records: {kpis['valid_products']:,}</div>
</header>

<!-- EXECUTIVE OVERVIEW -->
<div class="section">
  <h2>Executive Overview</h2>
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-value">{kpis['avg_rating']:.2f}</div>
      <div class="kpi-label">Average Rating</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{kpis['avg_discount']:.1f}%</div>
      <div class="kpi-label">Average Discount</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{kpis['high_rating_share']:.1f}%</div>
      <div class="kpi-label">High-Rating Share (≥4.0)</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{kpis['median_rating_count']:,.0f}</div>
      <div class="kpi-label">Median Review Count</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{kpis['price_discount_corr']:.3f}</div>
      <div class="kpi-label">Discount-Rating Correlation</div>
    </div>
  </div>

  <div class="insight-box">
    <strong>Headline:</strong> The catalog shows strong overall customer satisfaction with {kpis['high_rating_share']:.1f}% of products rated 4.0 or above. However, deeper discounts show a <em>weak negative correlation</em> with ratings (r = {kpis['price_discount_corr']:.3f}), suggesting that aggressive discounting does not buy customer love — it may even signal lower perceived quality. The median product garners {kpis['median_rating_count']:,.0f} reviews, but engagement is heavily concentrated in a few blockbuster SKUs.
  </div>

  <div class="chart">
    <img src="data:image/png;base64,{charts['kpi_dashboard']}" alt="KPI Dashboard">
  </div>
</div>

<!-- CATEGORY PERFORMANCE -->
<div class="section">
  <h2>Category Performance Breakdown</h2>
  <p>Products span {len(cat_stats)} top-level categories. <strong>{cat_stats.iloc[0]['top_category']}</strong> dominates with {cat_stats.iloc[0]['product_count']:,} products ({cat_stats.iloc[0]['product_count']/kpis['total_products']*100:.1f}% of catalog), while smaller categories show mixed performance.</p>

  <div class="two-col">
    <div class="chart">
      <img src="data:image/png;base64,{charts['category_rating']}" alt="Category Rating">
    </div>
    <div class="chart">
      <img src="data:image/png;base64,{charts['category_engagement']}" alt="Category Engagement">
    </div>
  </div>

  <h3>Top-Level Category Summary</h3>
  {html_table(['Category', 'Products', 'Avg Rating', 'Avg Discount', 'Median Reviews', 'Total Reviews'], cat_rows, ['left','right','right','right','right','right'])}

  <div class="insight-box">
    <strong>Key Insight:</strong> <span class="tag tag-good">Best Rated</span> <strong>{best_cat['top_category']}</strong> leads with {best_cat['avg_rating']:.2f} stars, while <span class="tag tag-bad">Needs Attention</span> <strong>{worst_cat['top_category']}</strong> trails at {worst_cat['avg_rating']:.2f}. Engagement is heavily skewed: <strong>{most_engaged_cat['top_category']}</strong> drives {most_engaged_cat['total_reviews']/cat_stats['total_reviews'].sum()*100:.1f}% of all reviews despite being only {most_engaged_cat['product_count']/kpis['total_products']*100:.1f}% of products.
  </div>

  <h3>Leading Sub-Categories</h3>
  {html_table(['Top Category', 'Sub-Category', 'Products', 'Avg Rating', 'Avg Discount'], subcat_rows, ['left','left','right','right','right'])}
</div>

<!-- PRICING & DISCOUNT STRATEGY -->
<div class="section">
  <h2>Pricing & Discount Strategy Analysis</h2>
  <p>This section directly addresses management's highest priority: <em>Do deeper discounts drive higher satisfaction?</em></p>

  <div class="chart">
    <img src="data:image/png;base64,{charts['discount_rating_scatter']}" alt="Discount vs Rating Scatter">
  </div>

  <div class="insight-box">
    <strong>Finding:</strong> The correlation between discount percentage and customer rating is <strong>r = {kpis['price_discount_corr']:.3f}</strong> — a weak <em>negative</em> relationship. Deeper discounts are associated with slightly <em>lower</em> ratings, not higher. Meanwhile, discount depth has virtually no correlation with review volume (r = {kpis['discount_count_corr']:.3f}), meaning discounts do not meaningfully boost engagement either.
  </div>

  <div class="two-col">
    <div>
      <h3>Performance by Discount Depth</h3>
      {html_table(['Discount Segment', 'Products', 'Avg Rating', 'Avg Discount', 'Median Reviews'], discount_rows, ['left','right','right','right','right'])}
    </div>
    <div>
      <h3>Performance by Price Segment</h3>
      {html_table(['Price Segment', 'Products', 'Avg Rating', 'Avg Discount', 'Median Reviews'], price_rows, ['left','right','right','right','right'])}
    </div>
  </div>

  <div class="chart">
    <img src="data:image/png;base64,{charts['discount_segment']}" alt="Discount Segment Performance">
  </div>

  <div class="chart">
    <img src="data:image/png;base64,{charts['price_segment']}" alt="Price Segment Performance">
  </div>

  <div class="chart">
    <img src="data:image/png;base64,{charts['correlation_heatmap']}" alt="Correlation Heatmap">
  </div>
</div>

<!-- CUSTOMER ENGAGEMENT -->
<div class="section">
  <h2>Customer Engagement & Rating Distribution</h2>

  <div class="two-col">
    <div class="chart">
      <img src="data:image/png;base64,{charts['rating_distribution']}" alt="Rating Distribution">
    </div>
    <div class="chart">
      <img src="data:image/png;base64,{charts['top_engaged']}" alt="Top Engaged Products">
    </div>
  </div>

  <h3>Top 10 Most Reviewed Products</h3>
  {html_table(['Product', 'Category', 'Price', 'Discount', 'Rating', 'Reviews'], engaged_rows, ['left','left','right','right','right','right'])}

  <div class="insight-box">
    <strong>Engagement Pattern:</strong> The top-reviewed products share three traits: (1) they sit in high-velocity categories like cables and mobile accessories, (2) they carry moderate discounts (30–60%), and (3) they maintain ratings of 4.0+. Exceptionally deep discounts (>70%) are rare among top sellers and do not appear to accelerate review accumulation.
  </div>
</div>

<!-- REVIEW SENTIMENT SNAPSHOT -->
<div class="section">
  <h2>Review Sentiment Snapshot</h2>
  <p>A qualitative scan of review titles from high-rated (≥4.0) and low-rated (≤3.0) products reveals distinct thematic patterns.</p>

  <div class="two-col">
    <div>
      <h3>Positive Themes <span class="tag tag-good">High Rated</span></h3>
      <p style="font-size:0.9rem;color:var(--muted);">Most frequent words in 4+ star review titles:</p>
      <ul class="sentiment-list">
        {''.join([f'<li><strong>{w}</strong> ({c} mentions)</li>' for w,c in positive_words])}
      </ul>
      <p style="margin-top:12px;font-size:0.9rem;color:var(--muted);">Sample titles:</p>
      <ul style="font-size:0.88rem;">
        {''.join([f'<li>"{t}"</li>' for t in pos_sample])}
      </ul>
    </div>
    <div>
      <h3>Negative Themes <span class="tag tag-bad">Low Rated</span></h3>
      <p style="font-size:0.9rem;color:var(--muted);">Most frequent words in ≤3 star review titles:</p>
      <ul class="sentiment-list">
        {''.join([f'<li><strong>{w}</strong> ({c} mentions)</li>' for w,c in negative_words])}
      </ul>
      <p style="margin-top:12px;font-size:0.9rem;color:var(--muted);">Sample titles:</p>
      <ul style="font-size:0.88rem;">
        {''.join([f'<li>"{t}"</li>' for t in neg_sample])}
      </ul>
    </div>
  </div>

  <div class="insight-box">
    <strong>Sentiment Insight:</strong> Positive reviews center on <em>speed, durability, charging performance, and value</em>. Negative reviews cluster around <em>quality issues, charging problems, durability failures, and compatibility</em>. The sentiment gap is functional, not aesthetic — customers judge these products on whether they work reliably over time.
  </div>
</div>

<!-- STRATEGIC RECOMMENDATIONS -->
<div class="section">
  <h2>Strategic Recommendations</h2>

  <div class="recommendation">
    <h4>1. Rethink Deep-Discount Promotions</h4>
    <p>Data shows a <strong>weak negative correlation (r = {kpis['price_discount_corr']:.3f})</strong> between discount depth and customer rating. Discounts above 70% do not yield higher satisfaction or materially higher review volume. Shift promotional budget from blanket deep discounts to targeted category-specific campaigns in mid-discount ranges (30–50%), where ratings hold steady and margins are better protected.</p>
  </div>

  <div class="recommendation">
    <h4>2. Prioritize Quality in Underperforming Categories</h4>
    <p><strong>{worst_cat['top_category']}</strong> scores {worst_cat['avg_rating']:.2f} — the lowest among all categories — yet carries an average discount of {worst_cat['avg_discount']:.1f}%. Deep discounts are not compensating for quality gaps. Recommend a quality audit of SKUs in this category, supplier negotiation, or assortment pruning before further margin investment.</p>
  </div>

  <div class="recommendation">
    <h4>3. Double Down on High-Engagement, High-Rating SKUs</h4>
    <p>{kpis['high_rating_share']:.1f}% of products already rate 4.0+, but a small subset drives the majority of reviews. Identify the shared attributes of top-engaged products (e.g., price point, brand, feature set) and expand the assortment with similar profiles. Use these as anchor SKUs in marketing rather than loss-leading deep discounts.</p>
  </div>

  <div class="recommendation">
    <h4>4. Address Functional Failure Modes Highlighted in Reviews</h4>
    <p>Negative review themes repeatedly cite charging failures, durability issues, and compatibility problems. These are <em>preventable</em> quality-control gaps. Implement stricter QC checkpoints and require suppliers to certify longevity standards. A 0.1-point rating improvement at scale can lift category conversion meaningfully.</p>
  </div>

  <div class="recommendation">
    <h4>5. Optimize Price Segmentation</h4>
    <p>Budget and mid-range segments dominate the catalog but show variable rating performance. Premium segments (₹1.5K–5K) offer an opportunity: they maintain competitive ratings with room for healthier margins. Test expanding premium-tier private-label or exclusive-brand SKUs where discount pressure is lower and customer satisfaction is sustained.</p>
  </div>
</div>

<footer>
  Report generated by automated analytics pipeline. All metrics derived directly from data.csv ({kpis['total_products']:,} records).<br>
  &copy; {datetime.now().year} Internal Analytics Team
</footer>

</div>
</body>
</html>
'''

with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
    f.write(html)

print("Report written to /app/output/final_report.html")
